import workcell

def status():
    return workcell.call("arm", "status").data["tip_mm"]

def go_above(x, y, z=120):
    # ensure we're high enough first
    st = status()
    if st[2] < 115:
        # step up
        while status()[2] < 118:
            r = workcell.call("arm", "step", "5")
            if not r.ok:
                print("step up fail", r.text)
                workcell.call("arm", "status")
                return False
    r = workcell.call("arm", "move", f"{x:.2f}", f"{y:.2f}", f"{z:.2f}")
    print("MOVE", r.text.split("\n")[0] if r.text else r.text, "ok", r.ok)
    if not r.ok:
        workcell.call("arm", "status")
        return False
    return True

def find_contact(z_min=36, coarse=-2, fine=-1):
    """Descend until Fz>0.35. Return (z, fz) or None."""
    # coarse until z < 100 or force
    while True:
        st = status()
        if st[2] < 100:
            break
        r = workcell.call("arm", "step", "-5")
        if not r.ok:
            print("fail", r.text)
            return None
        if r.data["fz_N"] > 0.3:
            return r.data["z_mm"], r.data["fz_N"]
    # medium
    while True:
        st = status()
        if st[2] < z_min:
            return None
        dz = "-1" if st[2] < 100 else "-2"
        r = workcell.call("arm", "step", dz)
        if not r.ok:
            print("fail", r.text)
            return None
        if r.data["fz_N"] > 0.35:
            return r.data["z_mm"], r.data["fz_N"]
        if r.data["z_mm"] < z_min:
            return None

def retract():
    for i in range(20):
        if status()[2] > 115:
            return True
        r = workcell.call("arm", "step", "5")
        if not r.ok:
            print("retract fail", r.text)
            workcell.call("arm", "status")
            return False
    return True

# map contact height along x at y=60
for x in [546, 549, 551, 553, 555, 557, 560, 565, 575, 585, 595]:
    print(f"\n==== probe x={x} ====")
    if not go_above(x, 60, 120):
        break
    c = find_contact()
    if c is None:
        print("  no contact")
    else:
        st = status()
        ft = workcell.call("ft", "read", "200").data
        print(f"  CONTACT tip=({st[0]:.2f},{st[1]:.2f},{st[2]:.2f}) stepz={c[0]:.2f} Fz={ft['fz']:.2f} Fx={ft['fx']:.2f} Fy={ft['fy']:.2f}")
    if not retract():
        break
print("MAP DONE", status())
